return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-09-25T17:31:44+00:00','po-revision-date'=>'2026-09-25T17:31:44+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A fast, privacy-respecting live chat for your website. Answers visitors with AI when you are busy, hands them to you when they need a person, and emails you anything you miss. Under 10 KB on the page and no requests at all until somebody opens it.'=>'Brz i privatnost usmjeren live chat za vašu web-lokaciju. Odgovara posjetiteljima pomoću umjetne inteligencije kada ste zauzeti, preusmjerava ih na vas kada trebaju živu osobu i šalje vam e-poštu o svemu što ste propustili. Manje od 10 KB na stranici i bez ikakvih zahtjeva dok ga netko ne otvori.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Settings'=>'Postavke','That does not look like a Zinn® Chat key. Copy it from the Live chat page of your Zinn Digital® dashboard — it starts with zc_.'=>'To ne izgleda kao ključ za Zinn® Chat. Kopirajte ga sa stranice Live chat na nadzornoj ploči Zinn Digital® – počinje s zc_.','Add your chat key before switching the chat on — without it there is nothing for the widget to connect to.'=>'Dodajte svoj ključ za chat prije nego što uključite chat — bez njega widget se nema s čime povezati.','Live chat for this site. Visitors get an answer straight away, you get anything you miss by email, and the whole thing is under 10 KB on the page.'=>'Razgovor uživo za ovu stranicu. Posjetitelji odmah dobivaju odgovor, sve što propustite stiže vam e-poštom, a cijela stvar zauzima manje od 10 KB na stranici.','The chat is live on this site.'=>'Razgovor je aktivan na ovoj stranici.','The chat is switched off. Nothing is loaded on your site.'=>'Chat je isključen. Ništa nije učitano na vašoj stranici.','Chat key'=>'Ključ za chat','Copy this from the Live chat page of your %s.'=>'Kopirajte ovo sa stranice uživo chata vašeg %s.','Zinn Digital® dashboard'=>'Zinn Digital® upravljačka ploča','Show the chat'=>'Prikaži chat','Show the chat window to visitors of this site'=>'Prikaži prozor za chat posjetiteljima ove stranice','Until you tick this, the plugin adds nothing at all to your pages — no script, no cookie, no requests.'=>'Dok to ne označite, dodatak ne dodaje apsolutno ništa na vaše stranice – ni skriptu, ni kolačić, ni zahtjeve.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički vodiči','Read the %s user guide'=>'Pročitajte korisnički priručnik za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, dnevne sigurnosne kopije, besplatna migracija i upravljačka ploča prilagođena osobama koje upravljaju s više web-mjesta.','The Zinn® marketplace'=>'Zinn® tržnica','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajite postojeće web-lokacije, domene i postavljanja poveznica, uz sigurno čuvanje novca sve dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude kojima je to životni poziv','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globalno tržište slobodnih zanimanja: pregledajte više od 10.000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i dopustite im da daju ponude.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju Zinn Digital®.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru cjelovitosti i nije instalirano.','Everything here keeps working for nothing, for ever. Pro is for when one person answering, and a month of history, stops being enough.'=>'Sve ovdje nastavlja raditi besplatno, zauvijek. Pro je namijenjen kada jedna osoba koja odgovara i mjesec dana povijesti više nisu dovoljni.','As many colleagues answering at once as you like — the free plugin allows one.'=>'Onoliko kolega koliko god želite može odgovarati istovremeno – besplatni dodatak omogućuje samo jednog.','Every conversation kept for ever, instead of thirty days.'=>'Svaki razgovor zauvijek sačuvan, umjesto trideset dana.','Your own name on the chat window, with ours removed.'=>'Vaše vlastito ime u prozoru za chat, s uklonjenim našim.','Saved replies, transfer a conversation to a colleague, and business hours.'=>'Spremljeni odgovori, prijenos razgovora kolegi i radno vrijeme.','5,000 AI answers a month rather than 100.'=>'5.000 AI odgovora mjesečno umjesto 100.','Choose exactly which pages the chat appears on — or hide it from the checkout.'=>'Odaberite točno na kojim će se stranicama chat prikazivati – ili ga sakrijte na blagajni.','One licence covers three of your sites; ten-site licences are available.'=>'Jedna licenca pokriva tri vaše stranice; dostupne su licence za deset stranica.','See what Pro costs'=>'Pogledajte cijene Pro paketa','Already host a site with Zinn Digital®? Pro is included free — your key is on the %s.'=>'Već hostate stranicu na Zinn Digital®? Pro je uključen besplatno — vaš ključ se nalazi na %s.','Licences page of your dashboard'=>'Stranica s licencama vaše upravljačke ploče','Your licence is active.'=>'Vaša je licenca aktivna.','Your licence has run out but everything still works for a short while. Renew it to keep receiving updates.'=>'Vaša licenca je istekla, ali sve još uvijek radi nakratko. Obnovite je kako biste nastavili primati ažuriranja.','We do not recognise that licence key. Copy it again from the Licences page of your Zinn Digital® dashboard.'=>'Ne prepoznajemo taj licencni ključ. Kopirajte ga ponovno sa stranice Licences na svojoj Zinn Digital® nadzornoj ploči.','That key is for a different Zinn® plugin. The one you want is on the Licences page of your dashboard, next to Zinn® Chat Pro.'=>'Ta je ključna riječ namijenjena drugom Zinn® dodu. Onaj koji vam treba nalazi se na stranici Licences vaše nadzorne ploče, pored Zinn® Chat Pro.','Your licence has expired. Renew it from your Zinn Digital® dashboard to switch the Pro features back on.'=>'Vaša licenca je istekla. Obnovite je sa svoje Zinn Digital® nadzorne ploče kako biste ponovno uključili Pro značajke.','This licence has been cancelled.'=>'Ova je licenca otkazana.','This licence is on hold. Please get in touch and we will sort it out.'=>'Ova licenca je pauzirana. Molimo vas da nas kontaktirate kako bismo to riješili.','There is a billing problem on your Zinn Digital® account. Once it is settled the licence works again straight away.'=>'Postoji problem s naplatom na vašem računu za Zinn Digital®. Čim se to riješi, licenca će odmah ponovno raditi.','This licence came free with your Zinn® hosting, and that hosting has ended. Buy a licence, or start hosting with us again, to switch Pro back on.'=>'Ova licenca bila je besplatna uz vaš Zinn® hosting, a taj hosting je završio. Kupite licencu ili ponovno počnite koristiti naš hosting kako biste ponovno uključili Pro.','Every site on this licence is in use. Release one below, or upgrade to cover more sites.'=>'Svaka stranica na ovoj licenci se koristi. Oslobodite jednu u nastavku ili nadogradite kako biste pokrili više stranica.','We could not confirm your licence just now. Nothing has changed on your site; we will try again shortly.'=>'Trenutno nismo mogli potvrditi vašu licencu. Na vašoj stranici ništa nije promijenjeno; pokušat ćemo ponovno uskoro.','You do not have permission to manage licences on this site.'=>'Nemate dopuštenje za upravljanje licencama na ovoj stranici.','Your Pro licence'=>'Vaša Pro licenca','Licence key'=>'Licencni ključ','Copy it from the Licences page of your %s.'=>'Kopirajte ga sa stranice Licencije vašeg %s.','Renews on %s.'=>'Obnavlja se dana %s.','Using %1$d of %2$d sites.'=>'Korišteno je %1$d od %2$d web-mjesta.','In use on: %s. Release one from your dashboard, then try again.'=>'Trenutačno se koristi na: %s. Oslobođeno s vaše upravljačke ploče, pa pokušajte ponovno.','Save licence'=>'Spremi licencu','Remove it from this site'=>'Ukloni ga s ove stranice','Where the chat appears'=>'Prikaz chata','Show it'=>'Prikaži','Everywhere on this site'=>'Svugdje na ovoj stranici','Only on the pages I choose below'=>'Samo na stranicama koje odaberem u nastavku','Everywhere except the pages I choose below'=>'Svugdje osim na stranicama koje odaberem u nastavku','Page or post IDs'=>'ID-ovi stranica ili objava','Separate them with commas. The ID is in the address bar while you edit a page.'=>'Odvojite ih zarezima. ID se nalazi u adresnoj traci dok uređujete stranicu.','Whole content types'=>'Cijele vrste sadržaja','Signed-in visitors'=>'Prijavljeni posjetitelji','Hide the chat from people who are signed in to this site'=>'Sakrij chat od osoba koje su prijavljene na ovu web-lokaciju','Save where it appears'=>'Spremi tamo gdje se pojavljuje']];